// OrderService.checkout の中に直接書いた場合
for (let i = 0; i < 3; i++) {
  try { result = await this.#payments.charge(req); break; }
  catch (e) { if (!isTransient(e)) throw e; await sleep(200); }
}

} catch (e) {
  if (!(e instanceof PaymentTimeoutError)) {
    // 課金されていないと分かっている失敗だけ、その場でやり直せるようにする
    order.status = 'PAYMENT_FAILED';
    await this.#orders.save(order);
  }
  throw e;
}
